"""Second-version report evaluation metrics.

This module deliberately writes a separate ``eval_v2.json`` instead of adding
fields to ``eval.json``.  The original file remains the reproducibility anchor
for older ablations.  v2 re-evaluates the final report directly against the
reference report and adds fairer aggregate-ready records, especially for
imbalanced grade evaluation.
"""

from __future__ import annotations

import json
from pathlib import Path
from typing import Any

EVAL_V2_SCHEMA_VERSION = "eval_v2_fair_grade_20260820"

GRADE_TIERS = ("low", "intermediate", "high")
GRADE_ORDINAL = {"low": 0, "intermediate": 1, "high": 2}


def _normalise_grade(value: Any) -> str:
    text = str(value or "").strip().lower()
    if text in GRADE_TIERS:
        return text
    if any(s in text for s in ("high grade", "poorly differentiated", "grade 3", "grade iii", "grade 4", "grade iv", "g3", "g4")):
        return "high"
    if any(s in text for s in ("intermediate grade", "moderately differentiated", "moderate differentiation", "grade 2", "grade ii", "g2")):
        return "intermediate"
    if any(s in text for s in ("low grade", "well differentiated", "grade 1", "grade i", "g1")):
        return "low"
    return "unspecified"


def _ordinal_score(pred: str, ref: str) -> float | None:
    if pred not in GRADE_ORDINAL or ref not in GRADE_ORDINAL:
        return None
    dist = abs(GRADE_ORDINAL[pred] - GRADE_ORDINAL[ref])
    if dist == 0:
        return 1.0
    if dist == 1:
        return 0.5
    return 0.0


def grade_record_from_tier(tier_grade: dict[str, Any], *, fallback_field_grade: dict[str, Any] | None = None) -> dict[str, Any]:
    """Create an aggregate-ready grade record from direct tier evaluation."""
    field_grade = fallback_field_grade or {}

    # Prefer tier_details: it is generated by evaluate_diagnosis_tiers directly
    # from final report vs reference text. field_scores.grade is a legacy
    # hierarchy extraction fallback and is more prone to denominator drift.
    source = "tier_details.grade" if tier_grade else "field_scores.grade"
    row = tier_grade or field_grade
    ref = _normalise_grade(row.get("reference"))
    pred = _normalise_grade(row.get("prediction"))
    applicable = row.get("applicable") is True and ref in GRADE_TIERS
    ordinal = _ordinal_score(pred, ref) if applicable else None

    return {
        "source": source,
        "applicable": bool(applicable),
        "prediction": pred,
        "reference": ref,
        "ordinal_score": ordinal,
        "exact": (pred == ref) if applicable else None,
        "high_prediction": (pred == "high") if applicable else None,
        "always_high_ordinal_score": _ordinal_score("high", ref) if applicable else None,
        "ordinal_score_source_value": row.get("score"),
        "legacy_field_grade": field_grade,
        "tier_grade": tier_grade,
    }


def grade_record_from_eval(eval_data: dict[str, Any]) -> dict[str, Any]:
    """Fallback only: create a grade record from an existing legacy eval.json."""
    return grade_record_from_tier(
        (eval_data.get("tier_details") or {}).get("grade") or {},
        fallback_field_grade=(eval_data.get("field_scores") or {}).get("grade") or {},
    )


def aggregate_grade_fair(records: list[dict[str, Any]]) -> dict[str, Any]:
    """Aggregate grade with class-balance diagnostics.

    ``balanced_accuracy`` and ``macro_f1`` are the fairness-oriented headline
    numbers. ``ordinal_score`` is retained as a secondary ordinal metric but is
    reported next to the always-high baseline because it is prevalence-sensitive.
    """
    rows = [r for r in records if r.get("applicable") is True]
    empty = {
        "n_applicable": 0,
        "ordinal_score": 0.0,
        "exact_accuracy": 0.0,
        "balanced_accuracy": 0.0,
        "macro_f1": 0.0,
        "high_prediction_rate": 0.0,
        "always_high_ordinal_score": 0.0,
        "reference_distribution": {},
        "prediction_distribution": {},
        "recall_by_class": {},
        "f1_by_class": {},
    }
    if not rows:
        return empty

    recalls: dict[str, float] = {}
    f1s: dict[str, float] = {}
    for label in GRADE_TIERS:
        tp = sum(r.get("reference") == label and r.get("prediction") == label for r in rows)
        fp = sum(r.get("reference") != label and r.get("prediction") == label for r in rows)
        fn = sum(r.get("reference") == label and r.get("prediction") != label for r in rows)
        ref_n = tp + fn
        if ref_n:
            recalls[label] = tp / ref_n
        if tp + fp + fn:
            precision = tp / (tp + fp) if (tp + fp) else 0.0
            recall = tp / (tp + fn) if (tp + fn) else 0.0
            f1s[label] = 2 * precision * recall / (precision + recall) if (precision + recall) else 0.0

    def _mean(values: list[float | None]) -> float:
        nums = [float(v) for v in values if isinstance(v, (int, float))]
        return sum(nums) / len(nums) if nums else 0.0

    return {
        "n_applicable": len(rows),
        "ordinal_score": _mean([r.get("ordinal_score") for r in rows]),
        "exact_accuracy": sum(r.get("exact") is True for r in rows) / len(rows),
        "balanced_accuracy": sum(recalls.values()) / len(recalls) if recalls else 0.0,
        "macro_f1": sum(f1s.values()) / len(f1s) if f1s else 0.0,
        "high_prediction_rate": sum(r.get("high_prediction") is True for r in rows) / len(rows),
        "always_high_ordinal_score": _mean([r.get("always_high_ordinal_score") for r in rows]),
        "reference_distribution": {c: sum(r.get("reference") == c for r in rows) for c in GRADE_TIERS},
        "prediction_distribution": {
            **{c: sum(r.get("prediction") == c for r in rows) for c in GRADE_TIERS},
            "unspecified": sum(r.get("prediction") == "unspecified" for r in rows),
        },
        "recall_by_class": recalls,
        "f1_by_class": f1s,
    }


def _eval_result_payload(er: Any) -> dict[str, Any]:
    return {
        "bleu_1": er.bleu_1,
        "bleu_4": er.bleu_4,
        "rouge_1": er.rouge_1,
        "rouge_2": er.rouge_2,
        "morph_f1": er.morph_f1,
        "critical_recall": er.critical_recall,
        "composite_score": er.composite_score,
        "overclaim_rate": er.overclaim_rate,
        "section_sims": er.section_sims,
        "hierarchy_score": er.hierarchy_score,
        "field_scores": er.field_scores,
        "diagnosis_score": er.diagnosis_score,
        "broad_score": er.broad_score,
        "subtype_score": er.subtype_score,
        "malignancy_score": er.malignancy_score,
        "grade_score": er.grade_score,
        "tier_details": er.tier_details,
        "subtype_hit": er.diagnosis_hit,
        "predicted_diagnosis": er.predicted_diagnosis,
        "reference_diagnosis": er.reference_diagnosis,
        "errors": er.errors,
    }


def build_eval_v2_from_metrics(
    *,
    case_id: str,
    cancer_type: str,
    metrics: dict[str, Any],
    reference_name: str = "image_only",
    source: str = "direct_final_report_vs_reference",
) -> dict[str, Any]:
    """Build one case-level eval_v2 document from freshly computed metrics."""
    grade = grade_record_from_tier(
        (metrics.get("tier_details") or {}).get("grade") or {},
        fallback_field_grade=(metrics.get("field_scores") or {}).get("grade") or {},
    )
    return {
        "schema_version": EVAL_V2_SCHEMA_VERSION,
        "case_id": case_id,
        "cancer_type": cancer_type,
        "reference_name": reference_name,
        "source": source,
        "diagnostic_accuracy": {
            "diagnosis_score": metrics.get("diagnosis_score"),
            "broad_score": metrics.get("broad_score"),
            "subtype_score": metrics.get("subtype_score"),
            "malignancy_score": metrics.get("malignancy_score"),
            "grade_ordinal_score": grade.get("ordinal_score"),
            "grade_exact": grade.get("exact"),
        },
        "report_quality": {
            "composite_score": metrics.get("composite_score"),
            "morph_f1": metrics.get("morph_f1"),
            "critical_recall": metrics.get("critical_recall"),
            "overclaim_rate": metrics.get("overclaim_rate"),
            "rouge_1": metrics.get("rouge_1"),
            "rouge_2": metrics.get("rouge_2"),
            "bleu_1": metrics.get("bleu_1"),
            "bleu_4": metrics.get("bleu_4"),
        },
        "grade_fair": grade,
        "raw_metrics": metrics,
        "notes": {
            "grade": (
                "Case-level grade stores prediction/reference only. Fair headline "
                "metrics such as balanced_accuracy and macro_f1 are computed over "
                "a cohort from eval_v2.json files."
            )
        },
    }


def build_eval_v2_from_report(
    *,
    settings: Any,
    generated_report: str,
    reference_report: str,
    case_id: str,
    cancer_type: str,
    diagnosis_prediction: dict[str, Any] | None = None,
    known_site: bool = True,
    ref_facts_precomputed: dict[str, Any] | None = None,
    reference_name: str = "image_only",
) -> dict[str, Any]:
    """Evaluate final report text against reference text and build eval_v2."""
    from pathxai_agent_v2.eval.runner import EvalRunner

    runner = EvalRunner(settings)
    er = runner.evaluate_case(
        generated_report=generated_report,
        reference_report=reference_report,
        case_id=case_id,
        cancer_type=cancer_type,
        diagnosis_prediction=diagnosis_prediction,
        known_site=known_site,
        ref_facts_precomputed=ref_facts_precomputed,
    )
    return build_eval_v2_from_metrics(
        case_id=case_id,
        cancer_type=cancer_type,
        metrics=_eval_result_payload(er),
        reference_name=reference_name,
        source="direct_final_report_vs_reference",
    )


def build_eval_v2_from_legacy_eval(eval_data: dict[str, Any]) -> dict[str, Any]:
    """Fallback for legacy-only cases; prefer build_eval_v2_from_report."""
    metrics = {
        "bleu_1": eval_data.get("bleu_1"),
        "bleu_4": eval_data.get("bleu_4"),
        "rouge_1": eval_data.get("rouge_1"),
        "rouge_2": eval_data.get("rouge_2"),
        "morph_f1": eval_data.get("morph_f1"),
        "critical_recall": eval_data.get("critical_recall"),
        "composite_score": eval_data.get("composite_score"),
        "overclaim_rate": eval_data.get("overclaim_rate"),
        "section_sims": eval_data.get("section_sims"),
        "hierarchy_score": eval_data.get("hierarchy_score"),
        "field_scores": eval_data.get("field_scores"),
        "diagnosis_score": eval_data.get("diagnosis_score"),
        "broad_score": eval_data.get("broad_score"),
        "subtype_score": eval_data.get("subtype_score"),
        "malignancy_score": eval_data.get("malignancy_score"),
        "grade_score": eval_data.get("grade_score"),
        "tier_details": eval_data.get("tier_details"),
        "subtype_hit": eval_data.get("subtype_hit"),
        "predicted_diagnosis": eval_data.get("predicted_diagnosis"),
        "reference_diagnosis": eval_data.get("reference_diagnosis"),
        "errors": eval_data.get("errors"),
    }
    return build_eval_v2_from_metrics(
        case_id=str(eval_data.get("case_id", "")),
        cancer_type=str(eval_data.get("cancer_type", "")),
        metrics=metrics,
        source="fallback_from_legacy_eval_json",
    )


def write_eval_v2_from_legacy_eval(case_dir: str | Path, *, overwrite: bool = True) -> bool:
    """Fallback writer from eval.json when report/reference are unavailable."""
    case_path = Path(case_dir)
    eval_path = case_path / "eval.json"
    out_path = case_path / "eval_v2.json"
    if out_path.exists() and not overwrite:
        return True
    if not eval_path.exists():
        return False
    try:
        eval_data = json.loads(eval_path.read_text(encoding="utf-8"))
        out_path.write_text(json.dumps(build_eval_v2_from_legacy_eval(eval_data), indent=2, ensure_ascii=False), encoding="utf-8")
        return True
    except Exception:
        return False


def aggregate_eval_v2(case_dirs: list[str | Path]) -> dict[str, Any]:
    """Aggregate already-written eval_v2 files."""
    records = []
    for case_dir in case_dirs:
        path = Path(case_dir) / "eval_v2.json"
        if not path.exists():
            continue
        try:
            records.append(json.loads(path.read_text(encoding="utf-8")).get("grade_fair", {}))
        except Exception:
            continue
    return {
        "schema_version": EVAL_V2_SCHEMA_VERSION,
        "grade_fair": aggregate_grade_fair(records),
    }
